import numpy as np

def get_lr(current_step, total_steps, max_lr=2e-5, warmup_fraction=0.06):
    warmup_steps = int(total_steps * warmup_fraction)
    if current_step < warmup_steps:
        # Linear warmup from 0 to max_lr
        return max_lr * current_step / max(1, warmup_steps)
    else:
        # Linear decay from max_lr to 0
        remaining = total_steps - warmup_steps
        decay_steps = current_step - warmup_steps
        progress = decay_steps / max(1, remaining)
        return max_lr * (1.0 - progress)

total = 1000
max_lr = 2e-5
wf = 0.1

print(f'Warmup steps: {int(total * wf)}')
for step in [0, 60, 100, 500, 999]:
    lr = get_lr(step, total, max_lr, wf)
    print(f'Step {step:4d}: LR = {lr:.2e}')
